INSERT INTO businesses (business_id, business_name, slug, category_id, category, street_address, city, province, postal_code, country, full_address, latitude, longitude, geo_precision, contact_person, phone, phone_alt, fax, email, website, facebook_url, instagram_url, twitter_url, linkedin_url, youtube_url, hours_mon, hours_tue, hours_wed, hours_thu, hours_fri, hours_sat, hours_sun, description, is_featured, image_url, source, source_url, alt_source_urls, duplicates_merged) VALUES (4770, 'Al Dente Italian Restaurant', 'al-dente-italian-restaurant', 225, 'Restaurants, Catering & Take Out', '39 Main Street North', 'Markham', 'ON', 'L3P 1X3', 'Canada', '39 Main Street North, Markham, ON L3P 1X3', 43.86682, -79.2663, 'approx_city_centre', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Welcome to historic Markham Villageâ€™s best kept dining secret: Al Dente. Serving mouth-watering cuisine that ranges from the eclectic to traditional Al Dente exudes the consistency and confidence of itâ€™s Executive Chef of over seven years Shaun Kelly and Maitreâ€™ d of over 14 years Nomir Chowdhury. With over 20 years combined experience at this location their passion for the business has now evolved to the next level: Ownership. Whether it is casual dining on the patio or solarium to fine dining in the main room, Al Dente Restaurant promises a truly remarkable dining experience. Pickering', FALSE, NULL, 'vanakkamcanada.ca', 'https://vanakkamcanada.ca/tamil-business-listings/al-dente-italian-restaurant', NULL, 0);
INSERT INTO businesses (business_id, business_name, slug, category_id, category, street_address, city, province, postal_code, country, full_address, latitude, longitude, geo_precision, contact_person, phone, phone_alt, fax, email, website, facebook_url, instagram_url, twitter_url, linkedin_url, youtube_url, hours_mon, hours_tue, hours_wed, hours_thu, hours_fri, hours_sat, hours_sun, description, is_featured, image_url, source, source_url, alt_source_urls, duplicates_merged) VALUES (4771, 'All Star Wings & Ribs', 'all-star-wings-ribs', 225, 'Restaurants, Catering & Take Out', '9255 Woodbine Ave 11', 'Markham', 'ON', 'L6C 1Y9', 'Canada', '9255 Woodbine Ave 11, Markham, ON L6C 1Y9', 43.86682, -79.2663, 'approx_city_centre', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Launched in 2003, AllStar Wings & Ribs (a.k.a.: the Hottest spot in Markham) has built an impressive reputation for "the best wings in the GTA" as well as "truly excellent ribs". Wing Lovers trek from all parts of the city to indulge in one or more of AllStar''s 100+ (and growing!) flavors of wings. Casual, laid back atmosphere, fast friendly service, great food and (of course) really cold beer is what you can expect at AllStar. Come and see why we our customers call us the United Nations of Wings!', FALSE, NULL, 'vanakkamcanada.ca', 'https://vanakkamcanada.ca/tamil-business-listings/all-star-wings-ribs', NULL, 0);
