-- TamilTO business directory: vanakkamcanada.ca + vanikam.ca, merged & de-duplicated (8 Nov 2026)
CREATE TABLE categories (
  category_id INT PRIMARY KEY,
  category_name VARCHAR(150) NOT NULL UNIQUE,
  category_slug VARCHAR(160) NOT NULL UNIQUE
);

CREATE TABLE businesses (
  business_id INT PRIMARY KEY,
  business_name VARCHAR(255) NOT NULL,
  slug VARCHAR(255) UNIQUE NOT NULL,
  category_id INT,
  category VARCHAR(150),
  street_address VARCHAR(255),
  city VARCHAR(100),
  province VARCHAR(10),
  postal_code VARCHAR(10),
  country VARCHAR(50),
  full_address VARCHAR(400),
  latitude DECIMAL(9,6),
  longitude DECIMAL(9,6),
  geo_precision VARCHAR(30),
  contact_person VARCHAR(150),
  phone VARCHAR(20),
  phone_alt VARCHAR(20),
  fax VARCHAR(20),
  email VARCHAR(255),
  website VARCHAR(500),
  facebook_url VARCHAR(500),
  instagram_url VARCHAR(500),
  twitter_url VARCHAR(500),
  linkedin_url VARCHAR(500),
  youtube_url VARCHAR(500),
  hours_mon VARCHAR(50),
  hours_tue VARCHAR(50),
  hours_wed VARCHAR(50),
  hours_thu VARCHAR(50),
  hours_fri VARCHAR(50),
  hours_sat VARCHAR(50),
  hours_sun VARCHAR(50),
  description TEXT,
  is_featured BOOLEAN,
  image_url VARCHAR(500),
  source VARCHAR(100),
  source_url VARCHAR(500),
  alt_source_urls TEXT,
  duplicates_merged INT,
  FOREIGN KEY (category_id) REFERENCES categories(category_id)
);
CREATE INDEX idx_businesses_category ON businesses(category_id);
CREATE INDEX idx_businesses_city ON businesses(city);

